"""Inline profile, mandatory OTP linking for one/two emails, no modal and consistent navigation icons."""
import asyncio
from playwright.async_api import async_playwright
H='http://127.0.0.1:8010'
async def main():
 async with async_playwright() as pw:
  b=await pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);errors=[]
  async def page(mat):
   c=await b.new_context(viewport=dict(width=390,height=844));await c.route('https://**/*',lambda r:r.abort());p=await c.new_page();p.on('pageerror',lambda e:errors.append(str(e)));await p.goto(H+'/login');await p.locator('input[type=text]').first.fill(mat);await p.locator('input[type=password]').fill('PruebaSegura123!');await p.get_by_role('button',name='Iniciar Sesión',exact=True).click();await p.locator('.sicip-app-header').wait_for();return p
  p=await page('TESTUSER');panel=p.locator('[data-profile-panel]');await panel.wait_for();await panel.locator('[data-profile-form]').wait_for();assert await p.locator('dialog[open]').count()==0
  async def blocked():return await p.evaluate("async()=>{try{await SICIPCentral.api('/api/pases/registros',{method:'POST',body:'{}'});return 200}catch(e){return e.message}}")
  f=panel.locator('[data-profile-form]');await f.locator('[name=personal]').fill('persona@example.test');await f.get_by_role('button',name='Guardar y vincular correos').click();await panel.get_by_text('Datos guardados, pero falta vincular el correo.',exact=False).wait_for();await p.wait_for_function("async()=>{const r=await fetch('/__test/mail');return (await r.json()).some(x=>x.destino==='persona@example.test')}");mail=await(await p.request.get(H+'/__test/mail')).json();code=next(x['codigo'] for x in reversed(mail) if x['destino']=='persona@example.test');assert 'Vincula tus correos' in await blocked();verify=panel.locator('[data-verify=personal]');await verify.locator('input').fill('000000' if code!='000000' else '999999');await verify.get_by_role('button',name='Vincular correo').click();await panel.get_by_text('Código incorrecto.',exact=False).wait_for();await verify.locator('input').fill(code);await verify.get_by_role('button',name='Vincular correo').click();await panel.get_by_text('✓ Perfil guardado y correos vinculados.',exact=False).wait_for();assert 'Vincula tus correos' not in await blocked();assert await panel.is_visible();print('Perfil integrado: guardar exige código, error visible, vinculación completa y pantalla abierta.',flush=True)
  await f.locator('[name=institucional]').fill('persona@imss.gob.mx');await f.get_by_role('button',name='Guardar y vincular correos').click();await panel.get_by_text('Datos guardados, pero falta vincular el correo.',exact=False).wait_for();assert 'Vincula tus correos' in await blocked();await p.wait_for_function("async()=>{const r=await fetch('/__test/mail');return (await r.json()).some(x=>x.destino==='persona@imss.gob.mx')}");mail=await(await p.request.get(H+'/__test/mail')).json();code=next(x['codigo'] for x in reversed(mail) if x['destino']=='persona@imss.gob.mx');verify=panel.locator('[data-verify=institucional]');await verify.locator('input').fill(code);await verify.get_by_role('button',name='Vincular correo').click();await panel.get_by_text('✓ Perfil guardado y correos vinculados.',exact=False).wait_for();assert 'Vincula tus correos' not in await blocked();assert await p.evaluate('document.documentElement.scrollWidth<=innerWidth+1');assert await p.locator('dialog[open]').count()==0;print('Dos direcciones requieren vinculación individual; no hay confirmación falsa ni popup.',flush=True)
  await panel.get_by_role('button',name='Volver al inicio').click();await p.locator('.sicip-home').wait_for();await p.locator('.sicip-profile-icon').click();await p.locator('[data-profile-panel]').wait_for();assert await p.locator('dialog[open]').count()==0
  a=await page('TESTADMIN');await a.wait_for_function("document.querySelector('[data-central-exams] [data-uniform-icon] svg')");await a.locator('[aria-controls=sicip-sidebar]').click();await a.locator('[data-sicip-depto-btn]').click();await a.locator('[data-tools-toggle]').click();assert await a.locator('[data-central-exams] svg').count()==1;assert await a.locator('[data-sicip-depto-btn] [data-uniform-icon] svg').get_attribute('stroke-width')=='1.8';assert await a.locator('[data-access-id="personal.herramientas.nivelacion"] svg').count()==1;assert not errors,errors;await a.screenshot(path='/tmp/sicip-menu-icons-554.png');await b.close();print('Acceso posterior al perfil integrado e iconos de Exámenes y submódulos verificados.',flush=True)
asyncio.run(main())
